static int[] bfsShortestPath(List<List<Integer>> graph, int source) {
    int[] distance = new int[graph.size()];
    Arrays.fill(distance, -1);

    Queue<Integer> queue = new ArrayDeque<>();
    distance[source] = 0;
    queue.offer(source);

    while (!queue.isEmpty()) {
        int u = queue.poll();

        for (int v : graph.get(u)) {
            if (distance[v] == -1) {
                distance[v] = distance[u] + 1;
                queue.offer(v);
            }
        }
    }

    return distance;
