static List<Integer> topologicalSortDFS(List<List<Integer>> graph) {
    int n = graph.size();
    int[] state = new int[n];
    Deque<Integer> stack = new ArrayDeque<>();

    for (int i = 0; i < n; i++) {
        if (state[i] == 0 && !topoDFS(graph, i, state, stack)) {
            throw new IllegalArgumentException("Graph contains a cycle");
        }
    }

    return new ArrayList<>(stack);
}

static boolean topoDFS(
        List<List<Integer>> graph,
        int u,
        int[] state,
        Deque<Integer> stack) {

    state[u] = 1;

    for (int v : graph.get(u)) {
        if (state[v] == 1) {
            return false;
        }

        if (state[v] == 0 && !topoDFS(graph, v, state, stack)) {
            return false;
        }
    }

    state[u] = 2;
    stack.push(u);
    return true;
}

