import java.util.*;

static long[] dijkstra(List<List<Edge>> graph, int source) {
    int n = graph.size();
    long[] distance = new long[n];
    Arrays.fill(distance, Long.MAX_VALUE);
    distance[source] = 0;

    PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
    pq.offer(new long[]{source, 0});

    while (!pq.isEmpty()) {
        long[] current = pq.poll();
        int u = (int) current[0];
        long dist = current[1];

        if (dist != distance[u]) {
            continue;
        }

        for (Edge edge : graph.get(u)) {
            int v = edge.to;
            long newDistance = dist + edge.weight;

            if (newDistance < distance[v]) {
                distance[v] = newDistance;
                pq.offer(new long[]{v, newDistance});
            }
        }
    }

    return distance;
}

Bellman-Ford.code:
static long[] bellmanFord(int vertices, List<Edge> edges, int source) {
    long[] distance = new long[vertices];
    Arrays.fill(distance, Long.MAX_VALUE / 4);
    distance[source] = 0;

    for (int i = 1; i < vertices; i++) {
        boolean changed = false;

        for (Edge edge : edges) {
            if (distance[edge.from] == Long.MAX_VALUE / 4) {
                continue;
            }

            long candidate = distance[edge.from] + edge.weight;
            if (candidate < distance[edge.to]) {
                distance[edge.to] = candidate;
                changed = true;
            }
        }

        if (!changed) {
            break;
        }
    }

    for (Edge edge : edges) {
        if (distance[edge.from] != Long.MAX_VALUE / 4 &&
            distance[edge.from] + edge.weight < distance[edge.to]) {
            throw new IllegalArgumentException("Reachable negative cycle detected");
        }
    }

    return distance;
}

Floyd-Warshall.code:
static void floydWarshall(long[][] distance) {
    int n = distance.length;

    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (distance[i][k] == Long.MAX_VALUE ||
                    distance[k][j] == Long.MAX_VALUE) {
                    continue;
                }

                distance[i][j] = Math.min(
                    distance[i][j],
                    distance[i][k] + distance[k][j]
                );
            }
        }
    }
}

