static int[] zeroOneBFS(List<List<Edge>> graph, int source) {
    int n = graph.size();
    int[] distance = new int[n];
    Arrays.fill(distance, Integer.MAX_VALUE);
    distance[source] = 0;

    Deque<Integer> deque = new ArrayDeque<>();
    deque.addFirst(source);

    while (!deque.isEmpty()) {
        int u = deque.removeFirst();

        for (Edge edge : graph.get(u)) {
            int v = edge.to;
            int newDistance = distance[u] + edge.weight;

            if (newDistance < distance[v]) {
                distance[v] = newDistance;

                if (edge.weight == 0) {
                    deque.addFirst(v);
                } else {
                    deque.addLast(v);
                }
            }
        }
    }

    return distance;
}

