import java.util.*;

static class DSU {
    int[] parent;
    int[] rank;

    DSU(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    boolean union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);

        if (rootA == rootB) {
            return false;
        }

        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }

        return true;
    }
}

static long kruskal(int vertices, List<Edge> edges) {
    edges.sort(Comparator.comparingInt(e -> e.weight));
    DSU dsu = new DSU(vertices);
    long totalWeight = 0;
    int edgesUsed = 0;

    for (Edge edge : edges) {
        if (dsu.union(edge.from, edge.to)) {
            totalWeight += edge.weight;
            edgesUsed++;

            if (edgesUsed == vertices - 1) {
                break;
            }
        }
    }

    if (edgesUsed != vertices - 1) {
        throw new IllegalArgumentException("Graph is disconnected");
    }

    return totalWeight;
}

