import java.util.*;

static long prim(List<List<Edge>> graph, int start) {
    int n = graph.size();
    boolean[] visited = new boolean[n];

    PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
    pq.offer(new long[]{0, start});

    long totalWeight = 0;
    int visitedCount = 0;

    while (!pq.isEmpty()) {
        long[] current = pq.poll();
        long weight = current[0];
        int u = (int) current[1];

        if (visited[u]) {
            continue;
        }

        visited[u] = true;
        visitedCount++;
        totalWeight += weight;

        for (Edge edge : graph.get(u)) {
            if (!visited[edge.to]) {
                pq.offer(new long[]{edge.weight, edge.to});
            }
        }
    }

    if (visitedCount != n) {
        throw new IllegalArgumentException("Graph is disconnected");
    }

    return totalWeight;
}

