import java.util.*;

static void dfsOrder(
        List<List<Integer>> graph,
        int u,
        boolean[] visited,
        Deque<Integer> stack) {

    visited[u] = true;

    for (int v : graph.get(u)) {
        if (!visited[v]) {
            dfsOrder(graph, v, visited, stack);
        }
    }

    stack.push(u);
}

static void dfsCollect(
        List<List<Integer>> reversed,
        int u,
        boolean[] visited,
        List<Integer> component) {

    visited[u] = true;
    component.add(u);

    for (int v : reversed.get(u)) {
        if (!visited[v]) {
            dfsCollect(reversed, v, visited, component);
        }
    }
}

static List<List<Integer>> kosaraju(List<List<Integer>> graph) {
    int n = graph.size();
    boolean[] visited = new boolean[n];
    Deque<Integer> stack = new ArrayDeque<>();

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            dfsOrder(graph, i, visited, stack);
        }
    }

    List<List<Integer>> reversed = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        reversed.add(new ArrayList<>());
    }

    for (int u = 0; u < n; u++) {
        for (int v : graph.get(u)) {
            reversed.get(v).add(u);
        }
    }

    Arrays.fill(visited, false);
    List<List<Integer>> components = new ArrayList<>();

    while (!stack.isEmpty()) {
        int u = stack.pop();

        if (!visited[u]) {
            List<Integer> component = new ArrayList<>();
            dfsCollect(reversed, u, visited, component);
            components.add(component);
        }
    }

    return components;
}

Bridges - Tarjan DFS.code:
static int timer = 0;

static void findBridges(
        List<List<Integer>> graph,
        int u,
        int parent,
        int[] discovery,
        int[] low,
        List<int[]> bridges) {

    discovery[u] = low[u] = ++timer;

    for (int v : graph.get(u)) {
        if (v == parent) {
            continue;
        }

        if (discovery[v] == 0) {
            findBridges(graph, v, u, discovery, low, bridges);
            low[u] = Math.min(low[u], low[v]);

            if (low[v] > discovery[u]) {
                bridges.add(new int[]{u, v});
            }
        } else {
            low[u] = Math.min(low[u], discovery[v]);
        }
    }
}

