static int articulationTimer = 0;

static void findArticulationPoints(
        List<List<Integer>> graph,
        int u,
        int parent,
        int[] discovery,
        int[] low,
        boolean[] articulation) {

    discovery[u] = low[u] = ++articulationTimer;
    int children = 0;

    for (int v : graph.get(u)) {
        if (v == parent) {
            continue;
        }

        if (discovery[v] == 0) {
            children++;
            findArticulationPoints(
                graph, v, u, discovery, low, articulation
            );

            low[u] = Math.min(low[u], low[v]);

            if (parent != -1 && low[v] >= discovery[u]) {
                articulation[u] = true;
            }
        } else {
            low[u] = Math.min(low[u], discovery[v]);
        }
    }

    if (parent == -1 && children > 1) {
        articulation[u] = true;
    }
}

