static boolean colorGraph(
        boolean[][] graph,
        int k,
        int[] colors,
        int vertex) {

    if (vertex == graph.length) {
        return true;
    }

    for (int color = 1; color <= k; color++) {
        if (canUseColor(graph, colors, vertex, color)) {
            colors[vertex] = color;

            if (colorGraph(graph, k, colors, vertex + 1)) {
                return true;
            }

            colors[vertex] = 0;
        }
    }

    return false;
}

static boolean canUseColor(
        boolean[][] graph,
        int[] colors,
        int vertex,
        int color) {

    for (int i = 0; i < graph.length; i++) {
        if (graph[vertex][i] && colors[i] == color) {
            return false;
        }
    }

    return true;
}

Hamiltonian Path.code:
static boolean hamiltonianPath(
        boolean[][] graph,
        int[] path,
        boolean[] used,
        int position) {

    if (position == graph.length) {
        return true;
    }

    for (int vertex = 0; vertex < graph.length; vertex++) {
        if (used[vertex]) {
            continue;
        }

        if (position == 0 || graph[path[position - 1]][vertex]) {
            path[position] = vertex;
            used[vertex] = true;

            if (hamiltonianPath(graph, path, used, position + 1)) {
                return true;
            }

            used[vertex] = false;
        }
    }

    return false;
}

Transitive Closure - Warshall.code:
static boolean[][] transitiveClosure(boolean[][] graph) {
    int n = graph.length;
    boolean[][] reach = new boolean[n][n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            reach[i][j] = graph[i][j];
        }
        reach[i][i] = true;
    }

    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                reach[i][j] = reach[i][j] ||
                              (reach[i][k] && reach[k][j]);
            }
        }
    }

    return reach;
}
